const paths={home:'M3 10l9-7 9 7M5 9v12h5v-7h4v7h5V9',book:'M12 6C8 3 5 3 2 4v16c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-6-1-10 2v16',receipt:'M5 2h14v20l-3-2-4 2-4-2-3 2V2M8 7h8M8 11h8M8 15h5',goat:'M3 11c4-3 8-2 11-1l3-6 5 2-2 4-3 1-2 5v6h-3v-5H7l-2 5H2l2-8-1-3-2-4m16-3c-4-5-7-2-5 0m6 3h1',chart:'M4 20v-7h3v7H4zm7 0V7h3v13h-3zm7 0V3h3v17h-3z',cart:'M2 3h3l3 13h11l3-9H6M9 21h.1M18 21h.1',tag:'M3 13L14 2h8v8L11 21 3 13zM18 6h.1',pay:'M2 19l5-3h7l6-5c3 0 3 2 1 4l-6 6H7M2 15v7M12 2a4 4 0 1 0 0 8 4 4 0 1 0 0-8m0 2v4m-1-3h2',settings:'M9 3h6l1 4 4 1v7l-4 1-1 5H9l-1-5-4-1V8l4-1 1-4zm3 5a4 4 0 1 0 0 8 4 4 0 1 0 0-8',chevron:'M9 5l7 7-7 7',down:'M5 9l7 7 7-7',plus:'M12 4v16M4 12h16',minus:'M4 12h16',close:'M6 6l12 12M18 6L6 18',back:'M15 5l-7 7 7 7',camera:'M3 6h5l2-3h4l2 3h5v15H3V6zm9 4a4 4 0 1 0 0 8 4 4 0 1 0 0-8',users:'M9 3a4 4 0 1 0 0 8 4 4 0 1 0 0-8M2 22v-4c0-6 14-6 14 0v4m1-18c5 0 5 7 1 7m2 3c3 1 3 4 3 8',leaf:'M20 3C3 1 0 13 8 18c8 5 14-5 12-15zM5 22l10-13',med:'M9 5l10 10M4 10l6-6c6-6 14 2 8 8l-6 6c-6 6-14-2-8-8z',wallet:'M3 5h18v16H3V5zm0 0 14-3v3m-2 6h7v6h-7v-6m3 3h.1',cloud:'M6 18C-1 18 0 9 6 9c0-9 14-9 14 0 6 2 5 9-1 9H6m6 1V9m-4 4 4-4 4 4',save:'M4 3h14l3 3v15H3V3h1zm3 0v6h10V3M7 21v-8h10v8',filter:'M3 4h18l-7 8v8l-4-2v-6L3 4z',lock:'M6 10V7c0-8 12-8 12 0v3M4 10h16v12H4V10zm8 4v4',calendar:'M3 5h18v16H3V5zm4-3v6m10-6v6M3 10h18',check:'M4 12l5 5L21 5',download:'M12 2v14m-5-5 5 5 5-5M3 17v5h18v-5',edit:'M4 17 16 5l4 4L8 21H4v-4zm10-10 4 4',trash:'M3 6h18M8 6V3h8v3M5 6l1 16h12l1-16M10 10v8m4-8v8'};
function icon(k){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.receipt}"/></svg>`}
function btn(text,action,data='',cls=''){return `<button class="btn ${cls}" data-act="${action}" data-id="${esc(data)}">${esc(text)}</button>`}
function ib(k,action,data='',label=''){return `<button class="icon-btn" data-act="${action}" data-id="${esc(data)}" aria-label="${esc(label||action)}">${icon(k)}</button>`}
const native=typeof Native!=='undefined';let db,loadError=false,migrationPending=false;
try{const raw=native?Native.load():localStorage.getItem('bakra-hisab-v1');if(raw==='!ERROR!')throw Error('Phone data read nahi ho saka.');migrationPending=!!raw&&JSON.parse(raw).version<3;db=raw?E.migrate(JSON.parse(raw)):E.newDB();}catch(e){loadError=true;db=E.newDB();}
let employeeView='total',selectionMode=false,selectedEmployees=new Set();
const partnerOn=()=>E.hasPartner(db,db.current);
const ownerLabel=(shared,solo)=>partnerOn()?shared:solo;
let route='home',detailId='',goatFilter='Mojood',search='',cashFilter={type:'all',cat:'',from:'',to:'',sort:'newest'},form=null,preview=null,photoTarget='',restoreData=null,toastTimer,draftTimer,pinLocked=false;
const current=()=>db.seasons.find(s=>s.id===db.current),bySeason=k=>db[k].filter(e=>e.season===db.current),status=g=>E.goatStatus(db,g);
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4300)}
function persist(next){E.validate(next);next.revision=db.revision+1;next.updatedAt=new Date().toISOString();let ok;try{if(native)ok=Native.save(JSON.stringify(next));else{localStorage.setItem('bakra-hisab-v1',JSON.stringify(next));ok=true}}catch(e){ok=false}if(!ok)throw Error('Phone par save nahi hua. Storage check karein; form abhi khula hai.');db=next;syncHealth();}
function transact(fn,message=''){try{const next=cloneData(db);fn(next);next.audit=next.audit||[];next.audit.push({at:new Date().toISOString(),message});if(next.audit.length>300)next.audit=next.audit.slice(-300);persist(next);render();return true}catch(e){toast(e.message);return false}}
function ensureOpen(){if(!current()){openForm('season');return false}if(current().closed){toast('Season band hai. Home ke season menu se dobara kholein.');return false}return true}
function titlebar(title,sub='',back=false){return `<div class="topbar"><div class="brand">${back?ib('back','back','','Wapas'):'<div class="logo">'+icon('goat')+'</div>'}<div>${sub?`<div class="kicker">${esc(sub)}</div>`:''}<h1>${esc(title)}</h1></div></div>${ib('settings','nav','settings','Settings')}</div>`}
function row(title,sub,amount,ico='receipt',action='',id='',sign=''){return `<div class="row ${action?'clickable':''}" ${action?`role="button" tabindex="0" data-act="${action}" data-id="${esc(id)}"`:''}><div class="row-icon">${icon(ico)}</div><div class="row-main"><b>${esc(title)}</b><small>${esc(sub)}</small></div>${amount!==null?`<div class="amount ${sign==='-'?'out':'in'}">${sign} ${esc(typeof amount==='number'?fmt(amount):amount)}</div>`:icon('chevron')}</div>`}
function empty(title,sub,action='',label='',ico='goat'){return `<div class="card empty"><div class="metric-icon">${icon(ico)}</div><h2>${esc(title)}</h2><p>${esc(sub)}</p>${action?btn(label,action):''}</div>`}
function hero(label,n,sub,ico='wallet'){return `<div class="hero"><div class="eyebrow">${esc(label)}</div><div class="hero-value">${typeof n==='number'?fmt(n):esc(n)}</div><small>${esc(sub)}</small><div class="balance-icon">${icon(ico)}</div></div>`}
function metric(label,value,ico){return `<div class="card metric"><div class="metric-icon">${icon(ico)}</div><div><small>${esc(label)}</small><b>${esc(value)}</b></div></div>`}
function strip(title,sub,ico,act,id=''){return `<button class="partner-strip" data-act="${act}" data-id="${esc(id)}"><span class="row-icon">${icon(ico)}</span><span><b>${esc(title)}</b><small>${esc(sub)}</small></span><span class="chev">${icon('chevron')}</span></button>`}
function backupInfo(){if(!native)return{linked:false,last:0,revision:-1,auto:false};try{return JSON.parse(Native.backupStatus())}catch(e){return{}}}
function saveStatus(){const b=backupInfo();return `<div class="badge-line"><span class="dot"></span>Phone par saved ${!navigator.onLine?' · Offline':''}${b.linked?' · Backup '+(b.revision===db.revision?'file updated':'pending'):''}</div>`}
function ledgerRows(rows){return rows.map(r=>row(r.title,r.date+' · '+r.cat+' · '+r.account,r.amount,r.type==='goat'?'goat':r.dir==='in'?'pay':'receipt','entry',r.type+':'+r.id,r.dir==='in'?'+':'-')).join('')}
function home(){if(!current())return titlebar('Bakra Hisab','APNA HISAB')+empty('Apna pehla season banayein','Har saal ke bakray aur hisab alag. Internet ke baghair bhi app chalegi.','new-season','+ Naya season')+strip('Backup se restore','Purana phone reset hua?','cloud','backup');const s=current(),v=E.summary(db,db.current);return titlebar('Bakra Hisab','APNA KAROBAR')+`<button class="season" data-act="seasons"><span>${icon('calendar')}${esc(s.name)}${s.closed?' <small>Band</small>':''}</span><small>Season badlein ${icon('down')}</small></button>`+hero('Season balance',v.balance,ownerLabel('Sirf mere hissay ki In / Out','Cash In / Out'))+`<div class="grid">${metric('Mojood bakray',v.stock,'goat')}${metric('Bikay bakray',v.sold,'tag')}</div><div class="grid">${metric(ownerLabel('Mere hissay ka kharcha','Total kharcha'),fmt(v.expense),'receipt')}${metric('Total sales',fmt(v.sales),'chart')}</div>`+`<div class="card profit-card"><div class="eyebrow">Total Profit</div><div class="hero-value">${fmt(v.profit)}</div><small>${ownerLabel('Sale − bikay / wafat bakron ki cost − mere kharchay','Sale − bikay / wafat bakron ki cost − kharchay')}</small></div>`+healthHome()+strip('Customers se lena',fmt(v.receivable),'pay','nav','customers')+(partnerOn()?strip('Partner Hisab',v.partner===0?'Hisab barabar':fmt(Math.abs(v.partner))+(v.partner>0?' lena hai':' dena hai'),'users','nav','partner'):'')+`<div class="section-title"><h2>Jaldi entry</h2></div><div class="actions">${[['cart','Bakra khareedo','goat'],['tag','Sale karo','sale'],['receipt','Kharcha likho','expense'],['pay','Payment lo','receipt']].map(([i,l,k])=>`<button class="action-tile" data-act="form" data-id="${k}">${icon(i)}${l}</button>`).join('')}</div>`+saveStatus()+`<div class="section-title"><h2>Haal ki entries</h2><button class="text-btn" data-act="nav" data-id="cash">Sab dekho</button></div><div class="card">${ledgerRows(E.ledger(db,db.current).slice(0,4))||'<small>Abhi koi entry nahi.</small>'}</div>`}
function cash(){const all=E.ledger(db,db.current),s=E.summary(db,db.current);const list=E.sortRows(all.filter(r=>(cashFilter.type==='all'||r.dir===cashFilter.type)&&(!cashFilter.cat||r.cat===cashFilter.cat)&&(!cashFilter.from||r.date>=cashFilter.from)&&(!cashFilter.to||r.date<=cashFilter.to)),cashFilter.sort);return titlebar('Cash Book',ownerLabel('MERA HISSA','CASH BOOK'))+`<div class="grid">${metric('Total In',fmt(s.inc),'pay')}${metric('Total Out',fmt(s.out),'receipt')}</div>`+hero('Season balance',s.balance,ownerLabel('Sirf mere hissay ki In / Out','Cash In / Out'))+`<div class="section-title"><h2>Transactions</h2><div class="inline-actions">${ib('down','sort','','Sort by')}${ib('filter','filter','','Filters')}</div></div><div class="chips">${[['all','Sab'],['in','Cash In'],['out','Cash Out']].map(([k,l])=>`<button class="${cashFilter.type===k?'active':''}" data-act="cash-type" data-id="${k}">${l}</button>`).join('')}</div>`+(list.length?`<div class="card">${ledgerRows(list)}</div>`:empty('Koi entry nahi','Cash In ya Cash Out se shuru karein. Filter ho to usay clear karein.','','','book'))+btn('Cash Book PDF','print','cash','secondary no-print')+`<div class="cash-actions">${btn('+ Cash In','in')}${btn('- Cash Out','out','','secondary')}</div>`}
function goatList(){const stock=E.summary(db,db.current);const gs=bySeason('goats').filter(g=>(goatFilter==='Sab'||status(g)===goatFilter)&&[g.tag,g.breed,g.color,g.seller].some(v=>searchKey(v).includes(searchKey(search))));return titlebar('Bakray',ownerLabel('MERA STOCK','STOCK'))+`<div class="card stock-summary"><div class="summary-line"><span>Total bakray (Mojood)</span><b>${stock.stock}</b></div><div class="summary-line"><span>Total kharid raqam</span><b>${fmt(stock.stockValue)}</b></div></div><div class="badge-line stock-count">Total bakray: <b>${bySeason('goats').length}</b> · Is list mein: <b>${gs.length}</b></div><div class="search-wrap"><input class="search" data-search="goats" enterkeyhint="search" placeholder="Bakra number, rang ya seller..." value="${esc(search)}"><button class="search-submit" data-act="goat-search" aria-label="Search">${icon('search')}</button></div><div class="chips">${['Mojood','Bik gaya','Wafat','Transferred','Sab'].map(k=>`<button class="${goatFilter===k?'active':''}" data-act="goat-filter" data-id="${k}">${k}</button>`).join('')}</div>`+strip('Sehat / Medical','Record aur schedules','med','health-open')+`<div class="cash-actions">${btn('Add kro','form','goat')}${btn('Sell kro','form','sale','secondary')}</div>`+`<div style="height:14px"></div>`+(gs.length?`<div class="card">${gs.map(g=>`<div class="row clickable" data-act="goat" data-id="${g.id}" tabindex="0" role="button">${thumb(g)}<div class="row-main"><b>${esc(g.tag)} ${g.color?'· '+esc(g.color):''}</b><small>${esc(g.date)} · ${esc(status(g))}</small><b style="margin-top:6px;color:var(--green)">${fmt(g.cost)}</b></div>${icon('chevron')}</div>`).join('')}</div>`:empty('Yahan abhi bakray nahi','Photo ke saath single ya batch purchase record karein.'))}
function thumb(g){return g.photo?`<img class="thumb" src="${esc(g.photo)}" alt="${esc(g.tag)}">`:`<span class="thumb">${icon('goat')}</span>`}
function goatDetail(id){const g=db.goats.find(g=>g.id===id);if(!g)return empty('Record nahi mila','');const s=E.saleOf(db,g.id),ex=db.expenses.filter(e=>E.goatExpense(e,id)>0).map(e=>({...e,share:E.goatExpense(e,id)}));return titlebar(g.tag,'BAKRA DETAIL',true)+(g.photo?`<img class="photo-large" src="${esc(g.photo)}" alt="${esc(g.tag)}">`:`<div class="photo-large">${icon('goat')}</div>`)+`<div class="chips"><span class="pill">${esc(status(g))}</span><span class="pill">${esc(g.breed||'Nasl optional')}</span></div><div class="grid">${metric('Kharid',fmt(g.cost),'cart')}${metric('Direct cost',fmt(ex.reduce((n,e)=>n+e.share,0)),'med')}</div><div class="card">${[['Rang',g.color||'-'],['Weight',g.weight?g.weight+' kg':'-'],['Seller',g.seller||'-'],['Kharid date',g.date],['Note',g.note||'-']].map(([a,b])=>`<div class="summary-line"><span>${a}</span><b>${esc(b)}</b></div>`).join('')}</div><div class="stack" style="margin-top:15px">${!s&&!g.lossDate&&!g.transferred?btn('Sale karo','sale-goat',g.id):''}${btn('Sehat / Medical','health-open',g.id,'secondary')}${btn('Bakra edit karo','edit','goat:'+g.id,'secondary')}${btn('Bakra delete karo','delete','goat:'+g.id,'danger')}${!s&&!g.lossDate&&!g.transferred?btn('Wafat / loss record','loss',g.id,'secondary'):''}${g.lossDate?btn('Loss undo karo','undo-loss',g.id,'secondary'):''}${!s&&!g.lossDate&&!g.transferred?btn('Agley season mein transfer','transfer-goat',g.id,'secondary'):''}</div>${s?`<div class="section-title"><h2>${E.saleGoats(s).length>1?'Combined sale · '+E.saleGoats(s).length+' bakray':'Sale'}</h2></div><div class="card">${row(s.customer||'Cash customer',s.date,s.price,'tag','entry','sale:'+s.id)}${row('Baqi payment','Customers se lena',E.outstanding(db,s),'pay','customer',s.id)}</div>`:''}<div class="section-title"><h2>Direct kharchay</h2></div><div class="card">${ex.map(e=>row(e.title||e.category,e.date,e.share,'receipt','entry','expense:'+e.id,'-')).join('')||'<small>Abhi direct kharcha nahi.</small>'}</div>`}
function partners(){const rows=E.partnerLedger(db,db.current),n=rows.reduce((a,r)=>a+r.delta,0);return titlebar('Partner Hisab',(current()?.partnerName||'').toUpperCase(),true)+hero(n===0?'Hisab barabar':n>0?'Partner se lena':'Partner ko dena',Math.abs(n),'Temporary paisa Cash Book se alag')+btn('+ Lena / dena entry','form','partner')+`<div class="section-title"><h2>Aapas ki history</h2></div><div class="card">${rows.map(r=>row(r.title,r.date+' · '+(r.delta>0?'Lena barha':'Dena barha'),Math.abs(r.delta),'users','entry',r.type+':'+r.id,r.delta>0?'+':'-')).join('')||'<small>Hisab barabar hai.</small>'}</div>`}
function reports(){const v=E.summary(db,db.current),lines=[['Opening balance',current()?.opening||0],['Total In',v.inc],['Total Out',v.out],['Season balance',v.balance],['Total sales',v.sales],['Customers se lena',v.receivable],['Purchases',v.purchases],[ownerLabel('Mere hissay ka kharcha','Total kharcha'),v.expense],...categories.map(c=>[c,bySeason('expenses').filter(e=>e.category===c).reduce((n,e)=>n+e.share,0)]),['Bikay bakron ki cost',v.soldCost],['Loss stock cost',v.lossCost],['Unsold stock value',v.stockValue]];return titlebar('Reports','BUSINESS OVERVIEW')+`<div class="print-title"><h1>Bakra Hisab</h1><p>${esc(current()?.name)} · ${E.today()}</p></div>`+hero(v.profit>=0?'Season munafa':'Season nuqsan',Math.abs(v.profit),ownerLabel('Sales - sold/lost stock cost - mere expenses','Sales - sold/lost stock cost - expenses'))+`<div class="card">${lines.map(([a,b])=>`<div class="summary-line"><span>${a}</span><b>${fmt(b)}</b></div>`).join('')}</div><div class="notice">Unsold purchase alag stock hai. ${ownerLabel('Capital, personal nikasi aur partner settlement munafa nahi. Shared kharchay season expenses hain;','Capital aur personal nikasi munafa nahi. Kharchay season expenses hain;')} Selected feeding aur direct kharchay bakray ke sale profit mein shamil hain; general kharchay season mein count hotay hain.</div><div class="stack no-print">${btn('PDF / Print report','print','reports')}${btn('Cash Book PDF','print','cash','secondary')}${btn('Customers PDF','print','customers','secondary')}${btn('Mulazim Ka Hisab','employee-report','','secondary')}${btn('Cash Book CSV (Excel)','csv','','secondary')}${btn('Customers ka hisab','nav','customers','secondary')}${partnerOn()?btn('Partner ka hisab','nav','partner','secondary'):''}</div>`}
function settings(){return titlebar('Settings','APP PREFERENCES',true)+`<div class="card">${row('Sehat notifications','Offline reminders aur timing',null,'calendar','health-settings')}${row('Offline auto-save','Hamesha ON · Phone storage',null,'save','storage')}${row('Google Drive / file backup','Android file picker se location select',null,'cloud','backup')}${row('PIN lock','Optional app lock',null,'lock','pin')}${partnerOn()?row('Partner ka naam',current().partnerName,null,'users','partner-name'):''}${row('Payment accounts',db.settings.accounts.join(', '),null,'wallet','accounts')}</div><div class="notice">Bakra Hisab 1.3.3 · Personal-use build. Photos aur financial records aapke phone mein. Reset/uninstall se pehle backup phone ke bahar rakhein.</div>`+saveStatus()}
function backupScreen(){const b=backupInfo();return titlebar('Backup & restore','PHONE + GOOGLE DRIVE',true)+hero('Local data','Phone par saved',db.updatedAt?new Date(db.updatedAt).toLocaleString():'Abhi naya record','cloud')+`<div class="card"><h3>Google Drive / backup file</h3><p class="muted" style="margin-top:9px">Drive app installed ho to Android file picker ke menu mein Google Drive select karein. Backup ki file wahan banegi. Yeh Google sign-in/API sync nahi hai.</p><div class="summary-line"><span>Backup file</span><b>${b.linked?'Linked':'Not selected'}</b></div><div class="summary-line"><span>Aakhri file update</span><b>${b.last?new Date(b.last).toLocaleString():'Abhi nahi'}</b></div><label class="switch-row"><span>Automatic file backup<br><small>App khuli ho / dobara khule</small></span><input type="checkbox" data-toggle-auto ${b.auto?'checked':''} ${!b.linked?'disabled':''}></label>${b.error?`<div class="notice error">${esc(b.error)}</div>`:''}<div class="stack">${btn(b.linked?'Backup location badlein':'Google Drive / location choose','link-backup')}${btn('Backup abhi karo','backup-now','','secondary')}</div></div><div class="section-title"><h2>Manual backup</h2></div><div class="stack">${btn('Nayi backup file export','export-backup')}${btn('Backup se restore','restore','','secondary')}</div><div class="notice">File save hona cloud upload ki guarantee nahi. Google Drive app mein sync check karein. Purane versions ke liye dated manual backups rakhein. Background/closed app sync guaranteed nahi.</div>`}
function render(){const nav=[['home','Home','home'],['cash','Cash Book','book'],['expenses','Kharchay','receipt'],['goats','Bakray','goat'],['reports','Reports','chart']];let html='';if(loadError)html=titlebar('Data recovery')+empty('Data read nahi hua','Original local record overwrite nahi kiya gaya. Backup se restore karein.','restore','Restore backup','cloud');else{const pages={health:healthPage,home,cash,expenses,goats:goatList,reports,partner:partners,customers,employees,settings,backup:backupScreen,goat:()=>goatDetail(detailId),customer:()=>customerDetail(detailId),employee:()=>employeeDetail(detailId),category:()=>categoryDetail(detailId)};if(route==='partner'&&!partnerOn())route='home';if(!current()&&!['home','settings','backup'].includes(route))route='home';html=(pages[route]||home)()};$('#app').innerHTML=`<main data-route="${route}" class="app-wrap ${['cash','employee','category','goats'].includes(route)?'cash':''}">${html}</main><nav class="nav" aria-label="Main navigation">${nav.map(([k,l,i])=>`<button class="${route===k?'active':''}" data-act="nav" data-id="${k}">${icon(i)}<span>${l}</span></button>`).join('')}</nav>`;enhanceLists();}
const navigationHistory=[];
function nav(to,id=''){clearTimeout(draftTimer);closeModal();if(to!==route||id&&id!==detailId)navigationHistory.push({route,detailId,search,goatFilter,cashFilter:{...cashFilter},employeeView,scroll:window.scrollY});route=to;if(id)detailId=id;search='';if(!['employee','employees'].includes(to)){selectionMode=false;selectedEmployees.clear();}render();window.scrollTo(0,0)}

function sheet(title,body,foot=''){ $('#modal').innerHTML=`<div class="modal-overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="sheet-head"><h2>${esc(title)}</h2>${ib('close','close','','Band karein')}</header><div class="sheet-body">${body}</div>${foot?`<footer class="sheet-foot">${foot}</footer>`:''}</section></div>`;document.body.style.overflow='hidden'}
function closeModal(){clearTimeout(draftTimer);if(form&&!preview)saveDraft();$('#modal').innerHTML='';document.body.style.overflow='';form=null;preview=null;}
window.goBack=()=>{if(pinLocked)return;if(!$('#modal').innerHTML&&cancelListSelection())return;if($('#modal').innerHTML){if(preview&&form){preview=null;drawForm();}else closeModal();return;}if(selectionMode){selectionMode=false;selectedEmployees.clear();render();return;}const previous=navigationHistory.pop();if(previous){({route,detailId,search,goatFilter,cashFilter,employeeView}=previous);render();window.scrollTo(0,previous.scroll||0);}else if(route!=='home'){route=({goat:'goats',customer:'customers',employee:'employees',category:'expenses',backup:'settings'})[route]||'home';render();window.scrollTo(0,0);}else toast('Home par hain. Phone ka Home button app band karega.');};
function field(name,label,value='',type='text',required=false){return `<label class="field"><span>${esc(label)}${required?' *':''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="0.01" inputmode="decimal"':''}></label>`}
function select(name,label,options,value){return `<label class="field"><span>${esc(label)}</span><select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`}
function photoPicker(name,label){const data=form?.values?.[name];return `<div class="photo-picker" data-photo-box="${name}">${data?`<img src="${esc(data)}" alt="${esc(label)}">`:''}<div class="photo-heading">${icon('camera')}<b>${esc(label)}</b></div><div class="photo-buttons">${btn('Camera','photo',name+':camera','secondary')}${btn('Gallery','photo',name+':gallery','secondary')}${data?btn('Remove','remove-photo',name,'secondary'):''}</div></div>`}
function noteField(v){return `<label class="field"><span>Note (optional)</span><textarea name="note" rows="2">${esc(v||'')}</textarea></label>`}
const accounts=()=>db.settings.accounts.filter(a=>a!=='Partner paid');
function paymentFields(v,total='total'){return (partnerOn()?`<div class="form-grid">${field('paidByMe','Main ne diya (khali = baqi bill)',v.paidByMe??'','number')}${field('partnerPaid','Partner ne diya (optional)',v.partnerPaid??'','number')}</div>`:'')+select('account','Payment mode',accounts(),v.account||'Cash')}
const categories=['Feeding','Medicine','Salary','Transport','Kiraya','Mandi fee','Other'];
function updateSaleInfo(){const f=$('#entryForm'),box=$('#saleInfo');if(!f||!box)return;const ids=[...f.querySelectorAll('[name=saleGoat]:checked')].map(e=>e.value);const cost=ids.reduce((n,id)=>n+(db.goats.find(g=>g.id===id)?.cost||0),0);let price=0;try{price=E.money(f.elements.price.value)*(f.elements.priceMode.value==='each'?ids.length:1)}catch(e){}const single=ids.length===1;f.elements.priceMode.closest('.field').hidden=single;if(single)f.elements.priceMode.value='total';f.elements.price.closest('.field').querySelector('span').textContent=single?'Sale price *':'Price (upar chune huay tareeqay ke mutabiq) *';f.elements.received.closest('.field').querySelector('span').textContent=single?'Abhi received *':'Abhi received (poore lot ka) *';box.textContent=ids.length+' bakray · Kharid '+fmt(cost)+' · Total sale '+fmt(price);}
function expenseGoatFields(v){if(v.category!=='Feeding')return select('goat','Bakra (optional)',[['','General kharcha — bakra select nahi'],...bySeason('goats').map(g=>[g.id,g.tag])],v.goat||'');const selected=v.expenseGoats||v.allocations?.map(a=>a.goat)||[v.goat].filter(Boolean);const gs=bySeason('goats').filter(g=>status(g)==='Mojood'||selected.includes(g.id));return `<div class="section-title"><h2>Feeding ke bakray</h2></div><div class="chips"><button type="button" data-act="expense-all">Sab select karo</button><button type="button" data-act="expense-none">Clear</button></div><div class="sale-picks">${gs.map(g=>`<label class="sale-pick"><input type="checkbox" name="expenseGoat" value="${g.id}" ${selected.includes(g.id)?'checked':''}><span>${esc(g.tag)}</span></label>`).join('')}</div><p class="muted">Kharcha selected bakron mein barabar taqseem hoga. Koi select na ho to general kharcha.</p>`;}
function employeeReportPicker(){const es=bySeason('employees');sheet('Mulazim Ka Hisab',`<div class="chips"><button data-act="report-all">Sab select karo</button><button data-act="report-none">Clear</button></div><div class="sale-picks">${es.map(e=>`<label class="sale-pick"><input type="checkbox" name="reportEmployee" value="${e.id}"><span>${esc(e.name)}</span></label>`).join('')||'<p>Abhi koi mulazim nahi.</p>'}</div>`,btn('PDF / Print','employee-report-print')+btn('Wapas','close','','secondary'));}
function formBody(){const {kind,values:v}=form;let html='';if(kind==='health')html=healthFields(v);if(kind==='schedule')html=scheduleFields(v);
 if(kind==='season')html=field('name','Season ka naam',v.name,'text',true)+field('start','Start date',v.start,'date',true)+field('opening','Opening balance',v.opening||0,'number')+field('partnerName','Partner ka naam (optional)',v.partnerName||'');
 if(kind==='goat')html=photoPicker('photo','Bakray ki photo')+field('tag','Bakra number',v.tag,'text',true)+(!v.id?field('batch','Batch count (single ke liye 1)',v.batch||1,'number',true):'')+`<div class="form-grid">${field('color','Rang',v.color)}${field('breed','Nasl',v.breed)}</div>`+field('weight','Weight kg (optional)',v.weight,'number')+field('cost','Kharid price / batch total',v.cost,'number',true)+paymentFields(v,'cost')+field('seller','Seller (optional)',v.seller)+field('date','Kharid date',v.date,'date',true)+noteField(v.note);
 if(kind==='expense')html=select('category','Category',form.id?categories:categories.filter(c=>c!=='Salary'),v.category)+field('title','Kharcha / item',v.title)+field('total','Total bill',v.total,'number',true)+(partnerOn()?`<div class="form-grid">${field('share','Mera hissa',v.share,'number',true)}${field('quantity','Quantity (optional)',v.quantity)}</div>`+`<div class="chips"><button type="button" data-act="split" data-id="half">50 / 50</button><button type="button" data-act="split" data-id="mine">Sirf mera</button><button type="button" data-act="split" data-id="partner">Sirf partner</button></div>`:field('quantity','Quantity (optional)',v.quantity))+paymentFields(v)+expenseGoatFields(v)+(v.category==='Salary'?select('employee','Mulazim',[['','Naam title mein likhein'],...bySeason('employees').map(e=>[e.id,e.name])],v.employee||'')+field('month','Salary month',v.month||E.today().slice(0,7),'month',true):'')+field('date','Date',v.date,'date',true)+photoPicker('photo','Bill / receipt (optional)')+noteField(v.note);
 if(kind==='expense'&&v.payroll)html=field('total','Total salary',v.total,'number',true)+(partnerOn()?field('share','Mera hissa',v.share,'number',true):'')+field('date','Date',v.date,'date',true)+noteField(v.note)+`<div class="notice">Yeh salary credit hai. Di hui payment mulazim ki book mein alag edit karein.</div>`;
 if(kind==='sale'){const selected=v.goats||[v.goat].filter(Boolean),available=bySeason('goats').filter(g=>status(g)==='Mojood'||selected.includes(g.id)&&E.saleOf(db,g.id)?.id===form.id);html=`<div class="section-title"><h2>Bakray select karein</h2><button type="button" class="text-btn" data-act="sale-all">Sab select</button><button type="button" class="text-btn" data-act="sale-none">Clear</button></div><div class="sale-picks">${available.map(g=>`<label class="sale-pick"><input type="checkbox" name="saleGoat" value="${g.id}" ${selected.includes(g.id)?'checked':''}>${thumb(g)}<span class="sale-pick-text"><b>${esc(g.tag)}</b><small>Kharid ${fmt(g.cost)}</small></span></label>`).join('')}</div><div id="saleInfo" class="notice"></div>`+select('priceMode','Price ka tareeqa',[['total','Poore lot ki total price'],['each','Har bakray ki same price']],v.priceMode||'total')+field('price','Price (upar chune huay tareeqay ke mutabiq)',v.price,'number',true)+field('received','Abhi received (poore lot ka)',v.received||0,'number',true)+field('customer','Customer ka naam',v.customer)+field('phone','Customer phone',v.phone,'tel')+select('account','Payment mode',accounts(),v.account||'Cash')+field('date','Sale date',v.date,'date',true)+noteField(v.note);}

 if(kind==='receipt')html=select('sale','Customer / sale',bySeason('sales').filter(s=>E.outstanding(db,s)>0||s.id===v.sale).map(s=>[s.id,(s.customer||'Cash customer')+' · '+(E.saleTags(db,s))+' · Baqi '+fmt(E.outstanding(db,s))]),v.sale)+field('amount','Received amount',v.amount,'number',true)+select('account','Payment mode',accounts(),v.account||'Cash')+field('date','Date',v.date,'date',true)+noteField(v.note);
 if(kind==='general')html=select('direction','Entry', [['in','Cash In'],['out','Cash Out']],v.direction)+select('category','Category',v.direction==='in'?['Capital','Business income']:['Personal nikasi','Business expense'],v.category)+field('title','Entry ka naam',v.title)+field('amount','Amount',v.amount,'number',true)+select('account','Payment mode',accounts(),v.account||'Cash')+field('date','Date',v.date,'date',true)+noteField(v.note);
 if(kind==='partner')html=select('direction','Paisa',[['gave','Main ne partner ko diya'],['received','Partner ne mujhe diya']],v.direction)+select('title','Type',['Temporary paisa','Wapsi / settlement'],v.title)+field('amount','Amount',v.amount,'number',true)+field('date','Date',v.date,'date',true)+noteField(v.note)+`<div class="notice">Sirf Partner Hisab update hoga. Cash Book mein entry nahi.</div>`;
 if(kind==='employee')html=field('name','Mulazim ka naam',v.name,'text',true)+field('phone','Phone',v.phone,'tel')+field('amount','Mahana salary',v.amount,'number',true)+(partnerOn()?field('percent','Mera hissa (%)',v.percent??50,'number',true):'');
 if(kind==='salary'){const employee=db.employees.find(e=>e.id===v.employee);html=`<div class="notice">${esc(employee?.name)} · Salary ${fmt(employee?.amount||0)}. ${ownerLabel('Sirf mera hissa Cash Book se niklega.','Salary Cash Book mein kharcha hogi.')} Payment alag record karein.</div>`+field('month','Salary month',v.month||E.today().slice(0,7),'month',true)+field('date','Salary date',v.date,'date',true);}
 if(kind==='employeePayment')html=select('direction','Entry',[['paid','Mulazim ko diya / advance'],['returned','Mulazim ne wapas kiya']],v.direction||'paid')+(partnerOn()?select('payer','Kis ke paisay',[['me','Mere'],['partner','Partner ke']],v.payer||'me'):'')+field('amount','Raqam',v.amount,'number',true)+(partnerOn()?field('percent','Is payment mein mera hissa (%)',v.percent??db.employees.find(e=>e.id===v.employee)?.percent??50,'number',true):'')+select('account','Payment mode',accounts(),v.account||'Cash')+field('date','Date',v.date,'date',true)+noteField(v.note)+`<div class="notice">Payment salary dobara kharcha nahi banayegi. ${ownerLabel('Salary jama honay par aapka hissa Cash Book mein lagta hai.','Salary jama honay par Cash Book mein kharcha lagta hai.')}</div>`;
 if(['goat','sale'].includes(kind))html+=tradeFeeFields(v);
 return `<form id="entryForm">${html}<div id="formError" class="notice error" hidden role="alert"></div><div class="badge-line"><span class="dot"></span><span id="draftStatus">Draft local auto-save</span></div></form>`;
}
const formTitles={health:'Sehat / Medical record',schedule:'Naya schedule',salary:'Salary jama karo',employeePayment:'Mulazim payment / advance',season:'Naya season',goat:'Bakra khareedo',expense:'Kharcha likho',sale:'Sale karo',receipt:'Payment receive',general:'General entry',partner:'Partner entry',employee:'Mulazim'};
function openForm(kind,id='',defaults={}){if(kind!=='season'&&!ensureOpen())return;if(kind==='partner'&&!partnerOn())return;if(kind==='expense'&&defaults.category==='Salary'){nav('employees');return;}const table={goat:'goats',expense:'expenses',sale:'sales',receipt:'receipts',general:'general',partner:'partner',employee:'employees',season:'seasons',employeePayment:'employeePayments',health:'health',schedule:'schedules'}[kind];let item=id?db[table]?.find(e=>e.id===id):null;
 if(kind==='goat'&&(item?.carried||item?.transferred)){toast('Carried bakray ki cost source season se linked hai; uska record edit nahi.');return}
 let v={date:E.today(),start:E.today(),tag:'B-'+String(bySeason('goats').length+1).padStart(3,'0'),batch:1,category:'Feeding',direction:'in',account:'Cash',...defaults};if(item){v={...item};if(kind==='sale'){v.goats=E.saleGoats(item);v.priceMode='total';}for(const k of ['cost','total','share','paidByMe','amount','price','received','opening'])if(v[k]!=null)v[k]=val(v[k]);v.partnerPaid=(v.total??v.cost??0)-(v.paidByMe??0);}
 const key=db.current+':'+kind+':'+id;const draft=db.drafts[key];if(draft&&!item&&!Object.keys(defaults).length)v={...v,...draft};
 if(kind==='sale'&&!bySeason('goats').some(g=>status(g)==='Mojood'||(v.goats||[v.goat]).includes(g.id))){toast('Sale ke liye mojood bakra add karein.');return}if(kind==='receipt'&&!bySeason('sales').some(s=>E.outstanding(db,s)>0||s.id===v.sale)){toast('Customer ki koi baqi payment nahi.');return}
 if(item&&['goat','sale'].includes(kind))v={...v,...loadTradeFees(kind,item.id)};if(['health','schedule'].includes(kind))v={...v,...defaults};form={kind,id,values:v,key};preview=null;drawForm();}
function drawForm(){sheet(formTitles[form.kind],formBody(),btn('Preview','preview')+btn('Cancel','close','','secondary'));if(form.kind==='sale')updateSaleInfo();}
function readForm(){if(!form)return{};const f=$('#entryForm');if(!f)return form.values;const data=Object.fromEntries(new FormData(f).entries());if(form.kind==='expense'&&f.querySelector('[name=expenseGoat]'))data.expenseGoats=new FormData(f).getAll('expenseGoat');if(form.kind==='sale')data.goats=new FormData(f).getAll('saleGoat');if(['health','schedule'].includes(form.kind))data.goats=new FormData(f).getAll('healthGoat');form.values={...form.values,...data};return form.values;}
function saveDraft(){if(!form||preview||loadError)return;readForm();try{const next=cloneData(db);next.drafts[form.key]=form.values;persist(next);const st=$('#draftStatus');if(st)st.textContent='Draft phone par saved'}catch(e){const st=$('#draftStatus');if(st)st.textContent='Draft save nahi hua';}}
function showError(s){const el=$('#formError');if(el){el.hidden=false;el.textContent=s;el.scrollIntoView({block:'nearest'})}else toast(s)}
function buildPreview(){if(['health','schedule'].includes(form?.kind)){healthPreview();return;}try{const f=$('#entryForm');if(!f.reportValidity())return;const v=readForm(),kind=form.kind;const rec={...v,id:form.id||E.uid(),season:db.current};delete rec.partnerPaid;delete rec.batch;const rows=[];if(['goat','sale'].includes(kind)){rec.tradeFees=readTradeFees(v);for(const k of ['rent','mandi','rentShare','mandiShare','rentMe','mandiMe'])delete rec[k];for(const [k,l] of [['rent','Kiraya'],['mandi','Mandi fees']])if(rec.tradeFees[k].total)rows.push([l+' · '+ownerLabel('mera hissa','kharcha'),fmt(rec.tradeFees[k].share)]);}
 if(kind==='season'){if(!v.name.trim())throw Error('Season naam likhein.');if(db.seasons.some(s=>s.id!==form.id&&s.name.toLowerCase()===v.name.trim().toLowerCase()))throw Error('Is naam ka season pehle se hai.');rec.name=v.name.trim();rec.opening=E.money(v.opening);rec.closed=!!v.closed;rec.partnerName=v.partnerName?.trim()||'';if(form.id&&!!rec.partnerName!==!!db.seasons.find(s=>s.id===form.id)?.partnerName&&hasSeasonRecords(form.id))throw Error('Maujooda hisab walay season ka partner on/off nahi badal sakte. Naya season banayein.');rows.push(['Season',rec.name],['Opening balance',fmt(rec.opening)])}
 if(kind==='goat'||kind==='expense'){const total=E.money(kind==='goat'?v.cost:v.total),pp=partnerOn()?E.money(v.partnerPaid):0,paid=partnerOn()?(v.paidByMe===''||v.paidByMe==null?total-pp:E.money(v.paidByMe)):total;if(!v.payroll&&paid+pp!==total)throw Error('Main ne + partner ne di hui raqam total bill ke barabar honi chahiye.');rec.paidByMe=v.payroll?0:paid;const share=kind==='goat'||!partnerOn()?total:E.money(v.share);if(share>total)throw Error('Mera hissa total bill se zyada nahi ho sakta.');rec.account=paid===0&&pp>0?'Partner paid':v.account;
 if(kind==='goat'){rec.cost=total;if(!v.tag.trim())throw Error('Bakra number likhein.');const count=form.id?1:Number(v.batch||1);if(!Number.isInteger(count)||count<1||count>500)throw Error('Aik batch mein 1 se 500 bakray. Total record limit nahi.');rec.count=count;if(count>1&&v.photo)rows.push(['Photo','Batch ki same photo sab par; baad mein edit kar sakte hain']);if(bySeason('goats').some(g=>g.tag.toLowerCase()===v.tag.trim().toLowerCase()&&g.id!==form.id))throw Error('Bakra number pehle se hai.');rec.tag=v.tag.trim();rows.push(['Bakray',String(count)])}else{rec.total=total;rec.share=share;if(v.category==='Feeding'){E.allocateExpense(db,rec,v.expenseGoats||[]);rows.push(['Selected bakray',String(rec.allocations.length)]);for(const a of rec.allocations)rows.push([db.goats.find(g=>g.id===a.goat).tag+' · total / mera hissa',fmt(a.total)+' / '+fmt(a.share)]);}else{delete rec.allocations;}delete rec.expenseGoat;delete rec.expenseGoats;}
 rows.push([ownerLabel('Meri Cash Book Out','Cash Book Out'),fmt(share)]);if(partnerOn()&&!v.payroll)rows.push(['Partner adjustment',paid-share===0?'Barabar':fmt(Math.abs(paid-share))+(paid-share>0?' lena':' dena')]);}
 if(kind==='salary'){const employee=db.employees.find(e=>e.id===v.employee);if(!employee)throw Error('Mulazim nahi mila.');rows.push(['Mulazim',employee.name],['Salary (green In)',fmt(employee.amount)],[ownerLabel('Mera Cash Book Out','Cash Book Out'),fmt(Math.round(employee.amount*(partnerOn()?employee.percent:100)/100))]);}
 if(kind==='employeePayment'){rec.amount=E.money(v.amount);if(!rec.amount)throw Error('Raqam zero se zyada ho.');const percent=partnerOn()?Number(v.percent):100;if(!Number.isFinite(percent)||percent<0||percent>100)throw Error('Hissa 0 se 100% tak.');rec.share=Math.round(rec.amount*percent/100);rec.payer=partnerOn()?(v.payer||'me'):'me';rows.push(['Payment',fmt(rec.amount)],['Entry',rec.direction==='paid'?'Mulazim ko diya':'Mulazim se wapas'],['Cash Book','Dobara kharcha nahi']);}
 if(kind==='sale'){rec.goats=[...new Set(v.goats||[])];if(!rec.goats.length)throw Error('Kam az kam aik bakra select karein.');rec.goat=rec.goats[0];rec.price=E.money(v.price)*(v.priceMode==='each'?rec.goats.length:1);rec.received=E.money(v.received);if(!Number.isSafeInteger(rec.price)||rec.price<=0)throw Error('Sale price sahi likhein.');let cost=0;for(const id of rec.goats){const g=db.goats.find(g=>g.id===id);if(!g||g.season!==db.current||g.lossDate||g.transferred)throw Error('Selected bakra available nahi.');if(E.saleOf(db,id)&&E.saleOf(db,id).id!==form.id)throw Error('Bakra pehle se bik gaya.');cost+=g.cost;}const later=db.receipts.filter(r=>r.sale===form.id).reduce((n,r)=>n+r.amount,0);if(rec.received+later>rec.price)throw Error('Received payments sale price se zyada hain.');if(rec.price>rec.received+later&&(!v.customer?.trim()||!v.phone?.trim()))throw Error('Udhaar par customer name aur phone zaroori hain.');const saleCost=E.saleCosts(db,rec,rec.tradeFees);rows.push(['Selected bakray',String(rec.goats.length)],['Bakra numbers',E.saleTags(db,rec)],['Total kharid',fmt(cost)],['Total sale',fmt(rec.price)],['Sale − kharid (kharchon se pehle)',fmt(rec.price-cost)],[ownerLabel('In bakron ka kharcha (mera hissa)','In bakron ka kharcha'),fmt(saleCost.expense)],['Kul lagat (kharid + kharcha)',fmt(saleCost.total)],[saleCost.profit>=0?'Profit on this sale':'Loss on this sale',fmt(Math.abs(saleCost.profit))],['Cash Book In',fmt(rec.received)],['Baqi',fmt(rec.price-rec.received-later)]);delete rec.saleGoat;rec.priceMode='total';}

 if(['receipt','general','partner','employee'].includes(kind)){rec.amount=E.money(v.amount);if(!rec.amount)throw Error('Amount zero se zyada likhein.');}
 if(kind==='receipt'){const s=db.sales.find(s=>s.id===v.sale);if(!s||s.season!==db.current)throw Error('Sale select karein.');const old=db.receipts.find(r=>r.id===form.id)?.amount||0;if(rec.amount>E.outstanding(db,s)+old)throw Error('Received amount baqi raqam se zyada hai.');rows.push(['Cash Book In',fmt(rec.amount)],['Baqi',fmt(E.outstanding(db,s)+old-rec.amount)])}
 if(kind==='general'){rec.category=rec.direction==='in'?(['Capital','Business income'].includes(v.category)?v.category:'Capital'):(['Personal nikasi','Business expense'].includes(v.category)?v.category:'Personal nikasi');rows.push([rec.direction==='in'?'Cash In':'Cash Out',fmt(rec.amount)],['Category',rec.category]);}
 if(kind==='partner')rows.push(['Cash Book','Koi entry nahi'],['Partner '+(v.direction==='gave'?'se lena barhega':'ko dena barhega'),fmt(rec.amount)]);
 if(kind==='employee'){rec.percent=partnerOn()?Number(v.percent??50):100;rec.autoSalary=!!v.autoSalary;rec.salaryDay=Number(v.salaryDay||1);rec.autoFrom=v.autoFrom||E.today();rec.salarySkips=v.salarySkips||[];if(rec.percent<0||rec.percent>100)throw Error('Hissa 0 se 100% tak.');rows.push(['Mulazim',v.name],['Salary',fmt(rec.amount)]);if(partnerOn())rows.push(['Mera hissa',rec.percent+'%'])}
 if(kind!=='season'&&kind!=='employee'&&!/^\d{4}-\d{2}-\d{2}$/.test(rec.date))throw Error('Date sahi select karein.');
 preview={rec,kind,key:form.key,editing:!!form.id};sheet('Confirm entry',`<div class="card">${rows.map(([a,b])=>`<div class="summary-line"><span>${esc(a)}</span><b>${esc(b)}</b></div>`).join('')}</div>${form.id?'<div class="notice">Existing entry replace hogi; duplicate post nahi hogi.</div>':''}`,btn('Confirm aur save','confirm')+btn('Wapas','preview-back','','secondary'));
 }catch(e){showError(e.message)}}
function confirmEntry(){if(!preview)return;const pr=preview;const ok=transact(d=>{const r=pr.rec;if(pr.kind==='health'){E.saveHealth(d,r)}else if(pr.kind==='schedule'){E.upsert(d,'schedules',r);if(r.health&&r.slot){const h=d.health.find(h=>h.id===r.health);if(h){h[r.slot==='next'?'nextDate':'followDate']=r.date;h[r.slot==='next'?'time':'followTime']=r.time;}}}else if(pr.kind==='season'){E.upsert(d,'seasons',r);d.current=r.id}else if(pr.kind==='salary'){E.addSalary(d,d.employees.find(e=>e.id===r.employee),r.month,r.date)}else if(pr.kind==='goat'&&r.count>1){const base=r.tag;for(let i=0;i<r.count;i++){const tag=base+'-'+(i+1);if(d.goats.some(g=>g.season===r.season&&g.tag.toLowerCase()===tag.toLowerCase()))throw Error('Batch ID duplicate: '+tag);const cost=Math.floor(r.cost/r.count)+(i<r.cost%r.count?1:0);const paid=Math.min(cost,Math.max(0,r.paidByMe-d.goats.filter(g=>g.batchId===r.id).reduce((n,g)=>n+g.paidByMe,0)));E.upsert(d,'goats',{...r,id:E.uid(),tag,cost,paidByMe:paid,batchId:r.id,count:undefined})}}else{const table={goat:'goats',expense:'expenses',sale:'sales',receipt:'receipts',general:'general',partner:'partner',employee:'employees',season:'seasons',employeePayment:'employeePayments',health:'health',schedule:'schedules'}[pr.kind];delete r.count;E.upsert(d,table,r)}if(['goat','sale'].includes(pr.kind)){const sources=pr.kind==='goat'&&r.count>1?d.goats.filter(g=>g.batchId===r.id):[d[pr.kind==='goat'?'goats':'sales'].find(x=>x.id===r.id)];E.saveTradeFees(d,pr.kind,sources,r.tradeFees);sources.forEach(x=>delete x.tradeFees);}delete d.drafts[pr.key];});if(ok){form=null;preview=null;closeModal();render()}}
function entryDetail(key){const [type,id]=key.split(':');if(type==='opening'){toast('Opening entry season setup se aayi hai.');return}const table={goat:'goats',expense:'expenses',sale:'sales',receipt:'receipts',general:'general',partner:'partner',employee:'employees',season:'seasons',employeePayment:'employeePayments',health:'health',schedule:'schedules'}[type],r=db[table]?.find(e=>e.id===id);if(!r)return;const fields=Object.entries(r).filter(([k,v])=>!['id','season','photo','goat','sale','employee','origin','batchId','seq','payroll','legacySalary','tradeType','tradeId','tradeFee','tradeFees','salarySkips','autoFrom','salaryDay','autoSalary','allocations'].includes(k)&&v!==''&&v!=null);sheet('Entry detail',`${r.allocations?.length?'<div class=card>'+r.allocations.map(a=>'<div class=summary-line><span>'+esc(db.goats.find(g=>g.id===a.goat)?.tag||'Bakra')+'</span><b>'+fmt(a.share)+'</b></div>').join('')+'</div>':''}${r.photo?`<img class="photo-large" src="${esc(r.photo)}" alt="Receipt">`:''}<div class="card">${fields.map(([k,v])=>`<div class="summary-line"><span>${esc({paidByMe:ownerLabel('Main ne diya','Ada kiya'),share:ownerLabel('Mera hissa','Raqam'),total:'Total bill',cost:'Kharid',received:'Received',price:'Sale price',amount:'Amount',date:'Date',account:'Payment mode',title:'Naam',category:'Category'}[k]||k)}</span><b>${esc(['paidByMe','share','total','cost','received','price','amount'].includes(k)?fmt(v):String(v))}</b></div>`).join('')}</div>`,btn('Edit','edit',key)+btn('Delete','delete',key,'danger'))}
function ask(title,msg,action,id=''){sheet(title,`<p style="line-height:1.7">${esc(msg)}</p>`,btn('Confirm','confirm-action',action+'|'+id)+btn('Cancel','close','','secondary'))}
function download(text,name,mime='application/json'){if(native){Native.exportText(text,name,mime);return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function backupEnvelope(){return JSON.stringify({app:'BakraHisab',backupVersion:1,createdAt:Date.now(),data:db})}
function restorePreview(txt){try{if(txt.length>60*1024*1024)throw Error('Backup bohat bara hai.');const env=JSON.parse(txt);if(env.app!=='BakraHisab'||env.backupVersion!==1)throw Error('Yeh Bakra Hisab backup nahi.');restoreData=E.migrate(env.data);sheet('Restore preview',`<div class="card"><div class="summary-line"><span>Seasons</span><b>${restoreData.seasons.length}</b></div><div class="summary-line"><span>Bakray</span><b>${restoreData.goats.length}</b></div><div class="summary-line"><span>Expenses</span><b>${restoreData.expenses.length}</b></div><div class="summary-line"><span>Backup date</span><b>${esc(new Date(env.createdAt).toLocaleDateString())}</b></div></div><div class="notice error">Current data replace hoga. Pehle apna current backup export karein. Restore ke baad PIN setting is phone wali hi rahegi.</div>`,btn('Backup export','export-backup','','secondary')+btn('Replace aur restore','restore-confirm'));}catch(e){toast('Restore nahi hua: '+e.message)}}
function exportCsv(){const q=v=>'"'+String(v??'').replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Season','Date','Category','Title','In PKR','Out PKR','Mode'],...E.ledger(db,db.current).map(r=>[current().name,r.date,r.cat,r.title,r.dir==='in'?r.amount/100:'',r.dir==='out'?r.amount/100:'',r.account])];download('\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n'),'Bakra-Hisab-ledger.csv','text/csv')}
function photoSelect(key,source){if(!form)return;readForm();photoTarget=key;if(native){Native.photo(key,source==='camera');return}const f=$('#photoFile');f.value='';if(source==='camera')f.setAttribute('capture','environment');else f.removeAttribute('capture');f.click()}
function setPhoto(key,data){if(!form)return;readForm();form.values[key]=data;drawForm();saveDraft()}
function pinScreen(){if(!native){toast('PIN lock Android app mein available hai.');return}sheet('PIN lock',`<form id="pinForm">${Native.hasPin()?field('old','Mojooda PIN','','password',true):''}${field('pin','Naya PIN (4-8 digits); blank = disable','','password')}${field('confirm','PIN dobara','','password')}<div class="notice">PIN privacy lock hai, backup encryption nahi. PIN bhoolne par backup se reinstall/restore ki zaroorat ho sakti hai.</div></form>`,btn('PIN save karo','pin-save'))}
function lockApp(){if(!native||!Native.hasPin())return;pinLocked=true;$('#lock').innerHTML=`<div class="lock-layer"><div class="card"><div class="logo" style="margin-bottom:20px">${icon('goat')}</div><h2>Bakra Hisab</h2><p class="muted" style="margin:10px 0 20px">Apna PIN enter karein</p><form id="unlockForm">${field('pin','PIN','','password',true)}${btn('Unlock','unlock','','wide')}</form><small id="pinError"></small></div></div>`}
paths.settings='M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9.5 3h5l.5 3 2 1.2 2.8-1 2.5 4.3-2.3 2v2.3l2.3 2-2.5 4.3-2.8-1-2 1.2-.5 3h-5L9 21l-2-1.2-2.8 1-2.5-4.3 2.3-2v-2.3l-2.3-2 2.5-4.3 2.8 1L9 6z';
// Keep the gear inside its viewBox.
