const hasSeasonRecords=id=>['goats','expenses','sales','general','partner','employees'].some(k=>db[k].some(e=>e.season===id));
function expenseRows(rows){return E.sortRows(rows).map(e=>row(e.title||e.category,e.date+' · Total '+fmt(e.total),e.share,'receipt','entry','expense:'+e.id,'-')).join('')||'<small>Abhi koi kharcha nahi.</small>'}
function expenses(){return titlebar('Kharchay',ownerLabel('MERE KHARCHAY','KHARCHAY'))+hero(ownerLabel('Mere hissay ka kharcha','Total kharcha'),E.summary(db,db.current).expense,'Is season ke kharchay','receipt')+`<div class="actions">${categories.map(k=>`<button class="action-tile" data-act="expense-cat" data-id="${k}">${icon(({Feeding:'leaf',Medicine:'med',Salary:'users'})[k]||'receipt')}<span>${k}<small class="block">${fmt(bySeason('expenses').filter(e=>e.category===k).reduce((n,e)=>n+e.share,0))}</small></span></button>`).join('')}</div>`+strip('Mulazim aur salary','Payments, advance aur mahana salary','users','nav','employees')+`<div class="section-title"><h2>Expense history</h2></div><div class="card">${expenseRows(bySeason('expenses'))}</div>`}
function categoryDetail(category){const rows=bySeason('expenses').filter(e=>e.category===category);return titlebar(category,'KHARCHAY',true)+hero(ownerLabel('Mere hissay ka kharcha','Total kharcha'),rows.reduce((n,e)=>n+e.share,0),rows.length+' transactions','receipt')+`<div class="card">${expenseRows(rows)}</div><div class="cash-actions">${btn('+ Kharcha add karo','category-add',category)}</div>`}
function employees(){return titlebar('Mulazim','SALARY & PAYMENTS',true)+`<div class="employee-add">${btn('+ Mulazim add karo','form','employee')}</div><div class="section-title employee-list-heading"><h2>Mulazim list</h2><button class="text-btn compact-select" data-act="employee-select">${selectionMode?'Cancel':'Select'}</button></div>${selectionMode?`<div class="selection-bar">${btn('Sab select','employee-select-all','','secondary')}${btn('Delete ('+selectedEmployees.size+')','employees-delete','','danger')}</div>`:'<div class="badge-line">Long press se aik ya zyada mulazim select karein.</div>'}<div class="card">${bySeason('employees').map(e=>{const v=E.employeeSummary(db,e.id);return `<div class="employee-item" data-employee-id="${e.id}">${selectionMode?`<input type="checkbox" aria-label="Select ${esc(e.name)}" data-select-employee="${e.id}" ${selectedEmployees.has(e.id)?'checked':''}>`:''}${row(e.name,'Monthly '+fmt(e.amount)+(partnerOn()?' · Mera '+e.percent+'%':'')+' · '+(v.balance>=0?'Dena ':'Advance ')+fmt(Math.abs(v.balance)),null,'users','employee',e.id)}</div>`}).join('')||'<small>Mulazim add karke salary aur advance record karein.</small>'}</div>`}
function employeeDetail(id){const e=db.employees.find(e=>e.id===id);if(!e)return empty('Mulazim nahi mila','');const v=E.employeeSummary(db,id),rows=E.employeeLedger(db,id,employeeView);return `<div class="topbar"><div class="brand">${ib('back','back','','Wapas')}<div><div class="kicker">MULAZIM HISAB</div><h1>${esc(e.name)}</h1></div></div>${ib('more','employee-more',id,'More options')}</div>`+btn('Mulazim PDF','print','employee','secondary no-print')+hero(v.balance===0?'Hisab barabar':v.balance>0?'Mulazim ko dena':'Mulazim ke paas advance',Math.abs(v.balance),'Salary minus di hui net payments','users')+`<div class="grid">${metric('Total salary',fmt(v.earnings),'calendar')}${metric('Net payments',fmt(v.paid),'pay')}</div><div class="chips">${[['total','Total'],...(partnerOn()?[['me','Main ne diya'],['partner','Partner ne diya']]:[])].map(([key,label])=>`<button data-act="employee-view" data-id="${key}" class="${employeeView===key?'active':''}">${label}</button>`).join('')}</div>${employeeView!=='total'?`<div class="notice">${employeeView==='me'?'Meri':'Partner ki'} net payments: <b>${fmt(employeeView==='me'?v.mine:v.partner)}</b></div>`:''}<div class="card">${rows.map(r=>row(r.title,r.date+' · '+r.cat+(r.note?' · '+r.note:''),r.amount,r.type==='expense'?'calendar':'pay','entry',r.type+':'+r.id,r.dir==='in'?'+':'-')).join('')||'<small>Abhi koi transaction nahi.</small>'}</div><div class="notice">Salary green In hai. Payment / advance red Out hai. ${ownerLabel('Aapki Cash Book mein sirf salary ka aapka hissa count hota hai.','Cash Book mein salary count hoti hai.')}</div><div class="cash-actions">${btn('+ Cash In','employee-in',id)}${btn('- Cash Out','employee-pay',id,'secondary')}</div>`}
function seasonPicker(){sheet('Seasons',`<div class="card">${db.seasons.map(s=>`<div class="season-record">${row(s.name,s.closed?'Band season':'Active',db.current===s.id?'Selected':null,'calendar','select-season',s.id)}<div class="inline-actions">${btn('Edit','season-edit',s.id,'secondary')}${btn('Delete','season-delete',s.id,'danger')}</div></div>`).join('')}</div>${current()?`<div class="stack" style="margin-top:16px">${btn(current().closed?'Season dobara kholo':'Season band karo','toggle-season','','secondary')}</div>`:''}`,btn('+ Naya season','new-season'))}
function customers(){const ss=E.sortRows(bySeason('sales'));return titlebar('Customers se lena','SALE RECOVERY',true)+hero('Total baqi',E.summary(db,db.current).receivable,'Sales aur received payments')+btn('Customers PDF','print','customers','secondary no-print')+`<div class="card" style="margin-top:16px">${ss.map(s=>row(s.customer||'Cash customer',(E.saleTags(db,s))+' · '+(s.phone||s.date),E.outstanding(db,s),'pay','customer',s.id)).join('')||'<small>Abhi koi sale nahi.</small>'}</div>`}
function customerDetail(id){const s=db.sales.find(x=>x.id===id);if(!s)return'';const out=E.outstanding(db,s);return titlebar(s.customer||'Cash customer','CUSTOMER HISAB',true)+hero('Baqi payment',out,s.phone||'Phone record nahi')+`<div class="card"><div class="summary-line"><span>Total sale</span><b>${fmt(s.price)}</b></div><div class="summary-line"><span>Sale par received</span><b>${fmt(s.received)}</b></div><div class="summary-line"><span>Bakra</span><b>${esc(E.saleTags(db,s))}</b></div></div><div class="stack" style="margin-top:15px">${out?btn('Payment receive karo','receipt-sale',s.id):'<div class="notice">Payment poori ho gayi.</div>'}${btn('Customer PDF','print','customer','secondary')}${btn('Customer edit','edit','sale:'+s.id,'secondary')}${btn('Customer delete','customer-delete',s.id,'danger')}</div><div class="section-title"><h2>Payment history</h2></div><div class="card">${row('Sale par received',s.date,s.received,'pay','entry','sale:'+s.id,'+')}${E.sortRows(db.receipts.filter(r=>r.sale===id)).map(r=>row('Received',r.date,r.amount,'pay','entry','receipt:'+r.id,'+')).join('')}</div>`}
function deleteMessage(key){const [type,id]=key.split(':');if(type==='goat'&&E.saleOf(db,id)&&E.saleGoats(E.saleOf(db,id)).length>1)return 'Yeh bakra combined sale mein hai. Delete par poori combined sale aur uski receipts bhi hatengi; lot ke baqi bakray dobara stock mein aayenge. Totals badlenge. Ghalat selection ho to sale edit karein.';if(type==='goat')return 'Galti se add bakra delete hoga. Iski sale, receipts, direct kharchay aur transfer copies sab seasons se hatengi. Cash Book aur partner totals bhi update honge. Undo nahi hoga.';if(type==='employee')return 'Mulazim, uski salary aur payment history delete hogi. Cash Book aur partner totals bhi update honge. Undo nahi hoga.';return 'Entry delete hogi aur linked hisab dobara calculate hoga. Salary delete karne par uski payments rehti hain aur auto salary isi month ko dobara add nahi karegi. Undo nahi hoga.';}
function employeeMore(id){const e=db.employees.find(e=>e.id===id);sheet('More options',`<div class="stack">${btn('Salary & auto settings','salary-settings',id)}${btn('Mulazim edit','edit','employee:'+id,'secondary')}${btn('Mulazim delete','delete','employee:'+id,'danger')}</div><div class="notice">Auto salary ${e.autoSalary?'ON':'OFF'} · Har mahine ${e.salaryDay||1} tareekh. App band ho to pending salary agli baar kholne par add hogi.</div>`)}
function salarySettings(id){const e=db.employees.find(e=>e.id===id);sheet('Monthly salary settings',`<form id="salarySettings"><label class="switch-row"><span>Automatic monthly salary</span><input type="checkbox" name="auto" ${e.autoSalary?'checked':''}></label>${field('day','Har month tareekh (1–31)',e.salaryDay||1,'number',true)}${field('from','Schedule start date',e.autoFrom||E.today(),'date',true)}<div class="notice">31 tareekh na ho to month ki aakhri tareekh. Start date se aaj tak pending months save par add honge. OFF karne se purani entries nahi mitengi.</div></form>`,btn('Save settings','salary-settings-save',id))}
function catchUp(){if(loadError)return;try{const next=cloneData(db),n=E.accrueSalaries(next);if(n){persist(next);render();toast(n+' mahino ki salary add ho gayi.')}}catch(e){toast('Auto salary: '+e.message)}}
function initializeUpdate(){if(loadError)return;try{if(migrationPending){if(native){if(!Native.snapshotBeforeRestore())throw Error('Purane data ka safety backup nahi bana.');}else localStorage.setItem('bakra-hisab-pre-v2',localStorage.getItem('bakra-hisab-v1'));persist(db);migrationPending=false;}catchUp();}catch(e){loadError=true;toast('Update data save nahi hua: '+e.message)}}
function printPage(kind,employeeIds=null){const title=({cash:'Cash Book',customers:'Customers report',customer:'Customer hisab',reports:'Season report',employees:'Mulazim Ka Hisab',employee:'Mulazim hisab'})[kind]||'Report';let content='';const line=(a,b)=>`<div class="summary-line"><span>${esc(a)}</span><b>${esc(b)}</b></div>`;
 if(kind==='cash'){const v=E.summary(db,db.current);content=line('Total In',fmt(v.inc))+line('Total Out',fmt(v.out))+line('Balance',fmt(v.balance))+`<table><thead><tr><th>Date</th><th>Entry / category</th><th>In</th><th>Out</th></tr></thead><tbody>${E.ledger(db,db.current).map(r=>`<tr><td>${r.date}</td><td>${esc(r.title)}<br>${esc(r.cat)} · ${esc(r.account)}</td><td>${r.dir==='in'?fmt(r.amount):''}</td><td>${r.dir==='out'?fmt(r.amount):''}</td></tr>`).join('')}</tbody></table>`;}
 else if(kind==='employees'||kind==='employee'){const es=kind==='employee'?bySeason('employees').filter(e=>e.id===detailId):bySeason('employees').filter(e=>!employeeIds||employeeIds.includes(e.id));content=es.map(e=>{const v=E.employeeSummary(db,e.id);return `<section class="print-customer"><h2>${esc(e.name)}</h2>${line('Total salary',fmt(v.earnings))}${line('Net payments / advance',fmt(v.paid))}${line(v.balance>=0?'Mulazim ko dena':'Mulazim ke paas advance',fmt(Math.abs(v.balance)))}<table><thead><tr><th>Date</th><th>Entry</th><th>Salary / Wapsi (In)</th><th>Payment / Advance (Out)</th></tr></thead><tbody>${E.employeeLedger(db,e.id).slice().reverse().map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.title)} · ${esc(r.cat||'')}${r.note?'<br>'+esc(r.note):''}</td><td>${r.dir==='in'?fmt(r.amount):''}</td><td>${r.dir==='out'?fmt(r.amount):''}</td></tr>`).join('')}</tbody></table></section>`}).join('')||'<p>Abhi mulazim nahi.</p>';}
 else if(kind==='customers'||kind==='customer'){const sales=kind==='customer'?db.sales.filter(s=>s.id===detailId):bySeason('sales');content=sales.map(s=>`<section class="print-customer"><h2>${esc(s.customer||'Cash customer')}</h2><p>${esc(s.phone||'')} · ${esc(E.saleTags(db,s))}</p>${line('Sale',fmt(s.price))}${line('Received',fmt(s.price-E.outstanding(db,s)))}${line('Baqi',fmt(E.outstanding(db,s)))}${line(s.date+' · Sale par received',fmt(s.received))}${E.sortRows(db.receipts.filter(r=>r.sale===s.id)).map(r=>line(r.date+' · '+(r.account||'Cash'),fmt(r.amount))).join('')}</section>`).join('');}
 else{const temp=document.createElement('div');temp.innerHTML=reports();temp.querySelectorAll('.topbar,.no-print,.print-title').forEach(e=>e.remove());content=temp.innerHTML;}
 let root=$('#printDocument');if(!root){root=document.createElement('div');root.id='printDocument';document.body.appendChild(root)}root.innerHTML=`<h1>Bakra Hisab · ${title}</h1><p>${esc(current()?.name)} · ${E.today()}</p>${content}`;if(native)Native.printReport();else window.print();}

async function act(action,id=''){
 if(pinLocked&&!['unlock'].includes(action))return;
 try{
 if(listAction(action,id))return;if(action==='goat-search'){search=$('[data-search]')?.value||'';document.activeElement?.blur();render();return;}if(await healthAction(action,id))return;
 if(action==='expense-all'||action==='expense-none'){document.querySelectorAll('[name=expenseGoat]').forEach(x=>x.checked=action==='expense-all');readForm();saveDraft();return;}
 if(action==='employee-report'){employeeReportPicker();return;}
 if(action==='report-all'||action==='report-none'){document.querySelectorAll('[name=reportEmployee]').forEach(x=>x.checked=action==='report-all');return;}
 if(action==='employee-report-print'){const ids=[...document.querySelectorAll('[name=reportEmployee]:checked')].map(x=>x.value);if(!ids.length)return toast('Kam az kam aik mulazim select karein.');closeModal();printPage('employees',ids);return;}
 if(action==='sort'){sheet('Sort by',`<div class="stack">${[['newest','New to old'],['oldest','Old to new'],['amount-high','Amount: high to low'],['amount-low','Amount: low to high']].map(([k,l])=>btn(l,'sort-set',k,cashFilter.sort===k?'':'secondary')).join('')}</div>`);return}
 if(action==='sort-set'){cashFilter.sort=id;closeModal();render();return}
 if(action==='category-add'){if(id==='Salary'){nav('employees');return}openForm('expense','',{category:id});return}
 if(action==='employee-view'){employeeView=id;render();return}
 if(action==='employee-in'){sheet('Mulazim Cash In',`<div class="stack">${btn('Salary jama karo (green In)','salary-employee',id)}${btn('Mulazim ne paisa wapas kiya','employee-return',id,'secondary')}</div>`);return}
 if(action==='employee-pay'||action==='employee-return'){openForm('employeePayment','',{employee:id,direction:action==='employee-pay'?'paid':'returned',payer:'me'});return}
 if(action==='employee-more'){employeeMore(id);return}
 if(action==='salary-settings'){salarySettings(id);return}
 if(action==='salary-settings-save'){if(!ensureOpen())return;const f=$('#salarySettings');if(!f.reportValidity())return;const day=Number(f.elements.day.value),from=f.elements.from.value;if(!Number.isInteger(day)||day<1||day>31)return toast('Tareekh 1 se 31 tak ho.');if(transact(d=>{const e=d.employees.find(e=>e.id===id);e.autoSalary=f.elements.auto.checked;e.salaryDay=day;e.autoFrom=from;E.accrueSalaries(d);},'Salary settings saved'))closeModal();return}
 if(action==='employee-select'){selectionMode=!selectionMode;selectedEmployees.clear();render();return}
 if(action==='employee-select-all'){bySeason('employees').forEach(e=>selectedEmployees.add(e.id));render();return}
 if(action==='employees-delete'){if(!ensureOpen())return;if(!selectedEmployees.size)return toast('Mulazim select karein.');ask('Selected mulazim delete?',selectedEmployees.size+' mulazim aur unki tamam salary/payment history delete hogi. Cash Book aur partner totals dobara calculate honge.','employees-delete');return}
 if(action==='confirm-action'&&id==='employees-delete|'){if(transact(d=>{for(const key of selectedEmployees)E.remove(d,'employee',key)},'Selected mulazim delete ho gaye')){selectedEmployees.clear();selectionMode=false;closeModal();render();}return}
 if(action==='season-edit'){closeModal();openForm('season',id);return}
 if(action==='season-delete'){ask('Season delete?', 'Is season ke tamam bakray, sales, kharchay, customers, mulazim aur hisab delete hoga. Doosre seasons rahenge. Undo nahi hoga.','season-delete',id);return}
 if(action==='confirm-action'&&id.startsWith('season-delete|')){if(transact(d=>E.remove(d,'season',id.split('|')[1]),'Season delete ho gaya')){closeModal();nav('home')}return}
 if(action==='customer-delete'){if(!ensureOpen())return;sheet('Customer delete',`<p>Sirf customer ka naam / phone hata sakte hain aur sale ka hisab rahega. Galat sale ho to sale aur uski receipts bhi delete karein.</p>`,btn('Sirf customer hatao','customer-forget',id)+btn('Sale bhi delete','customer-sale-delete',id,'danger'));return}
 if(action==='customer-forget'){ask('Customer details hata dein?','Naam aur phone hat jayenge. Sale, received payments aur baqi raqam record mein rahengi.','customer-forget',id);return}
 if(action==='confirm-action'&&id.startsWith('customer-forget|')){if(transact(d=>{const s=d.sales.find(s=>s.id===id.split('|')[1]);s.customer='';s.phone='';},'Customer details delete ho gayin'))closeModal();return}
 if(action==='customer-sale-delete'){ask('Sale bhi delete?', 'Customer ki sale aur tamam receipts hatengi. Bakra dobara stock mein hoga. Cash Book In aur munafa update honge.','delete','sale:'+id);return}

 if(action==='sale-all'||action==='sale-none'){document.querySelectorAll('[name=saleGoat]').forEach(e=>e.checked=action==='sale-all');readForm();updateSaleInfo();saveDraft();return;}if(action==='nav'){nav(id);return}if(action==='back'){window.goBack();return}if(action==='close'){closeModal();return}
 if(action==='new-season'){closeModal();openForm('season');return}if(action==='seasons'){seasonPicker();return}if(action==='select-season'){if(transact(d=>{d.current=id},'')){closeModal();navigationHistory.length=0;route='home';cashFilter={type:'all',cat:'',from:'',to:'',sort:'newest'};render()}return}
 if(action==='toggle-season'){ask('Season '+(current().closed?'kholein':'band karein'),current().closed?'Entries dobara edit kar sakenge.':'Purana data rahega. New entries ke liye season reopen karna hoga.','toggle');return}
 if(action==='form'){openForm(id);return}if(action==='in'||action==='out'){if(!ensureOpen())return;sheet(action==='in'?'Cash In':'Cash Out',`<div class="stack">${action==='in'?btn('Sale ki baqi payment','form','receipt')+btn('Capital / general income','general-in','','secondary'):btn('Bakra kharidari','form','goat')+btn('Feeding / salary / kharcha','form','expense','secondary')+btn('Personal nikasi / general','general-out','','secondary')}</div>`);return}
 if(action==='general-in'||action==='general-out'){openForm('general','',{direction:action==='general-in'?'in':'out',category:action==='general-in'?'Capital':'Personal nikasi'});return}
 if(action==='goat-filter'){goatFilter=id;render();return}if(action==='cash-type'){cashFilter.type=id;render();return}if(action==='goat'){nav('goat',id);return}if(action==='customer'){nav('customer',id);return}
 if(action==='sale-goat'){openForm('sale','',{goat:id});return}if(action==='receipt-sale'){openForm('receipt','',{sale:id});return}
 if(action==='expense-cat'){nav('category',id);return}if(action==='employee'){if(selectionMode){selectedEmployees.has(id)?selectedEmployees.delete(id):selectedEmployees.add(id);render();return}nav('employee',id);employeeView='total';render();return}
 if(action==='salary-employee'){openForm('salary','',{employee:id,month:E.today().slice(0,7)});return}
 if(action==='entry'){entryDetail(id);return}if(action==='edit'){const [kind,key]=id.split(':');openForm(kind,key);return}
 if(action==='delete'){if(!ensureOpen())return;ask('Entry delete karein?',deleteMessage(id),'delete',id);return}
 if(action==='confirm-action'){const [what,key]=id.split('|');if(what==='toggle'){if(transact(d=>{d.seasons.find(s=>s.id===d.current).closed=!current().closed},'Season status updated'))closeModal()}if(what==='delete'){const [type,rid]=key.split(':');if(transact(d=>E.remove(d,type,rid),'Entry delete ho gayi')){form=null;closeModal();if(['goat','employee','customer'].includes(route))nav(({goat:'goats',employee:'employees',customer:'customers'})[route]);}}if(what==='undo-loss'){if(transact(d=>{const g=d.goats.find(g=>g.id===key);delete g.lossDate;delete g.lossNote},'Loss status hata diya'))closeModal()}return}
 if(action==='preview'){buildPreview();return}if(action==='preview-back'){preview=null;drawForm();return}if(action==='confirm'){confirmEntry();return}
 if(action==='split'){const f=$('#entryForm'),total=Number(f.elements.total.value||0);f.elements.share.value=id==='half'?Math.round(total*50)/100:id==='mine'?total:0;saveDraft();return}
 if(action==='photo'){const [key,source]=id.split(':');photoSelect(key,source);return}if(action==='remove-photo'){readForm();form.values[id]='';drawForm();saveDraft();return}
 if(action==='backup'){nav('backup');return}if(action==='storage'){sheet('Phone storage',`<div class="card"><h3>Offline auto-save ON</h3><p class="muted" style="margin-top:12px">Confirmed entries phone mein foran save hoti hain. Form drafts bhi auto-save hotay hain. Reset/uninstall se local data mit sakta hai.</p><div class="summary-line"><span>Data size</span><b>${(new Blob([JSON.stringify(db)]).size/1048576).toFixed(2)} MB</b></div></div>`,btn('Backup kholo','backup'));return}
 if(action==='link-backup'){if(native)Native.linkBackup();else toast('Google Drive / system file picker APK mein available hai.');return}if(action==='backup-now'){if(native)Native.backupNow();else act('export-backup');return}
 if(action==='export-backup'){if(native)Native.exportBackup();else download(backupEnvelope(),'Bakra-Hisab-'+E.today()+'.json');return}if(action==='restore'){if(native)Native.restore();else{$('#backupFile').value='';$('#backupFile').click()}return}
 if(action==='restore-confirm'){if(!restoreData)return;const next=cloneData(restoreData);try{if(native){if(!Native.snapshotBeforeRestore())throw Error('Current data ka safety snapshot nahi ban saka.')}else localStorage.setItem('pre-restore-snapshot',JSON.stringify(db));persist(next);loadError=false;restoreData=null;closeModal();navigationHistory.length=0;route='home';render();toast('Backup restore ho gaya.')}catch(e){toast('Restore failed: '+e.message)}return}
 if(action==='print'){printPage(id||route);return}if(action==='csv'){exportCsv();return}
 if(action==='partner-name'){sheet('Partner ka naam',`<form id="simpleForm">${field('name','Naam',current().partnerName,'text',true)}</form>`,btn('Save','partner-name-save'));return}if(action==='partner-name-save'){const name=$('#simpleForm').elements.name.value.trim();if(!name)return toast('Naam likhein.');if(transact(d=>d.seasons.find(s=>s.id===d.current).partnerName=name))closeModal();return}
 if(action==='accounts'){sheet('Payment accounts',`<div class="card">${db.settings.accounts.map(a=>`<div class="summary-line"><span>${esc(a)}</span><small>${a==='Cash'?'Default':'Optional'}</small></div>`).join('')}</div><form id="simpleForm" style="margin-top:20px">${field('name','Naya account naam','','text',true)}</form>`,btn('Account add','account-add'));return}if(action==='account-add'){const n=$('#simpleForm').elements.name.value.trim();if(!n||db.settings.accounts.includes(n))return toast('Naya unique naam likhein.');if(transact(d=>d.settings.accounts.push(n)))closeModal();return}
 if(action==='pin'){pinScreen();return}if(action==='pin-save'){const f=$('#pinForm'),p=f.elements.pin.value;if(p!==f.elements.confirm.value)return toast('Dono PIN same nahi.');if(Native.setPin(f.elements.old?.value||'',p)){closeModal();toast(p?'PIN enabled':'PIN disabled')}else toast('Mojooda PIN ya naya PIN sahi nahi. 4-8 digits use karein.');return}
 if(action==='unlock'){const p=$('#unlockForm').elements.pin.value;if(Native.verifyPin(p)){pinLocked=false;$('#lock').innerHTML='';openHealthTarget()}else $('#pinError').textContent='PIN sahi nahi. 5 attempts ke baad 30 sec rukna hoga.';return}
 if(action==='filter'){sheet('Cash Book filters',`<form id="filterForm">${field('from','Start date',cashFilter.from,'date')}${field('to','End date',cashFilter.to,'date')}${select('cat','Category',[['','Sab'],...new Set(E.ledger(db,db.current).map(r=>r.cat))],cashFilter.cat)}</form>`,btn('Apply','apply-filter')+btn('Clear','clear-filter','','secondary'));return}if(action==='apply-filter'){const f=$('#filterForm');cashFilter={...cashFilter,...Object.fromEntries(new FormData(f))};closeModal();render();return}if(action==='clear-filter'){cashFilter={type:'all',cat:'',from:'',to:'',sort:'newest'};closeModal();render();return}
 if(action==='loss'){if(!ensureOpen())return;sheet('Wafat / loss',`<form id="lossForm">${field('date','Date',E.today(),'date',true)}${field('note','Reason / note','','text',true)}</form><div class="notice">Stock kam hoga; sale ya cash receipt nahi. Kharid Out dobara count nahi hogi.</div>`,btn('Confirm loss','loss-save',id));return}if(action==='loss-save'){const f=$('#lossForm');if(!f.reportValidity())return;if(transact(d=>{const g=d.goats.find(g=>g.id===id);if(E.saleOf(d,id)||g.transferred)throw Error('Bakra mojood nahi.');g.lossDate=f.elements.date.value;g.lossNote=f.elements.note.value}))closeModal();return}if(action==='undo-loss'){if(ensureOpen())ask('Loss undo?','Bakra dobara mojood stock mein aayega.','undo-loss',id);return}
 if(action==='transfer-goat'){if(!ensureOpen())return;const dest=db.seasons.filter(s=>s.id!==db.current&&!s.closed);if(!dest.length)return toast('Pehle Home par naya season banayein, phir yahan wapas aayein.');sheet('Bakra transfer',`<form id="transferForm">${select('destination','Destination season',dest.map(s=>[s.id,s.name]),dest[0].id)}${field('date','Transfer date',E.today(),'date',true)}</form><div class="notice">Purchase cost carry hogi; na nayi sale, na duplicate purchase Out. Cash balance transfer alag opening capital entry se karein.</div>`,btn('Confirm transfer','transfer-save',id));return}
 if(action==='transfer-save'){const f=$('#transferForm');if(!f.reportValidity())return;const dest=f.elements.destination.value,date=f.elements.date.value;const ok=transact(d=>{const g=d.goats.find(g=>g.id===id);if(E.goatStatus(d,g)!=='Mojood')throw Error('Bakra available nahi.');let tag=g.tag;if(d.goats.some(x=>x.season===dest&&x.tag===tag))tag+='-carry';if(d.goats.some(x=>x.season===dest&&x.tag===tag))throw Error('Destination mein same ID hai. Pehle rename karein.');E.upsert(d,'goats',{...g,id:E.uid(),season:dest,tag,date,carried:true,origin:id,paidByMe:0});g.transferred=dest;g.transferDate=date;});if(ok)closeModal();return}
 }catch(e){toast(e.message||'Action complete nahi hua.')}
}
let longTimer,longStart=null,suppressClick=false;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-employee-id]');if(!el||selectionMode||el.querySelector('[data-list-key]'))return;longStart={x:e.clientX,y:e.clientY};longTimer=setTimeout(()=>{selectionMode=true;selectedEmployees.add(el.dataset.employeeId);suppressClick=true;render();},600)});
document.addEventListener('pointermove',e=>{if(longStart&&Math.hypot(e.clientX-longStart.x,e.clientY-longStart.y)>10)clearTimeout(longTimer)});
for(const event of ['pointerup','pointercancel'])document.addEventListener(event,()=>{clearTimeout(longTimer);longStart=null;});
document.addEventListener('contextmenu',e=>{if(e.target.closest('[data-employee-id]'))e.preventDefault()});
document.addEventListener('click',e=>{if(suppressClick){suppressClick=false;e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('change',e=>{if(e.target.dataset.selectEmployee){const id=e.target.dataset.selectEmployee;e.target.checked?selectedEmployees.add(id):selectedEmployees.delete(id);render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b){e.preventDefault();act(b.dataset.act,b.dataset.id||'')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')window.goBack();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-act]')){e.preventDefault();act(e.target.dataset.act,e.target.dataset.id)}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='unlockForm')act('unlock');else if(e.target.id==='entryForm')buildPreview()});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-search]')){e.preventDefault();act('goat-search');}});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){search=e.target.value;}if(e.target.closest('#entryForm')){if(form?.kind==='sale')updateSaleInfo();const er=$('#formError');if(er)er.hidden=true;clearTimeout(draftTimer);draftTimer=setTimeout(saveDraft,500)}});
document.addEventListener('change',e=>{if(form&&['health','schedule'].includes(form.kind)&&e.target.closest('#entryForm')){if(['expenseMode','kind'].includes(e.target.name)){readForm();drawForm();}if(['nextDays','date'].includes(e.target.name)&&form.kind==='health'){const f=$('#entryForm');if(f.elements.nextDays.value!=='')f.elements.nextDate.value=E.addDays(f.elements.date.value||E.today(),f.elements.nextDays.value);}if(e.target.name==='afterDays'&&form.kind==='schedule'){const f=$('#entryForm');if(f.elements.afterDays.value!=='')f.elements.date.value=E.addDays(E.today(),f.elements.afterDays.value);}}if(e.target.matches('[data-toggle-auto]')){if(native)Native.setAuto(e.target.checked);return}if(form&&e.target.closest('#entryForm')){if(form.kind==='salary'&&e.target.name==='date')$('#entryForm').elements.month.value=e.target.value.slice(0,7);if(form.kind==='sale')updateSaleInfo();if(e.target.name==='category'&&form.kind==='expense'){readForm();drawForm()}if(e.target.name==='direction'&&form.kind==='general'){readForm();form.values.category=form.values.direction==='in'?'Capital':'Personal nikasi';drawForm()}saveDraft()}});
$('#photoFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const bitmap=await createImageBitmap(f);const ratio=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas');c.width=bitmap.width*ratio;c.height=bitmap.height*ratio;c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);setPhoto(photoTarget,c.toDataURL('image/jpeg',.78));bitmap.close()}catch(e){toast('Image read nahi hui. Doosri photo try karein.')}});
$('#backupFile').addEventListener('change',async e=>{if(e.target.files[0])restorePreview(await e.target.files[0].text())});
window.nativeEvent=(type,payload)=>{if(type==='healthOpen'){openHealthTarget();return;}if(type==='photo'){const p=JSON.parse(payload);setPhoto(p.key,p.data)}else if(type==='restore')restorePreview(payload);else if(type==='backup'||type==='backupAuto'){if(route==='backup')render();if(type==='backup'&&payload)toast(payload)}else if(type!=='cancel')toast(payload)};
window.addEventListener('appResume',()=>{catchUp();syncHealth();openHealthTarget()});
window.addEventListener('appPause',()=>{saveDraft();lockApp()});
window.addEventListener('beforeunload',()=>saveDraft());window.addEventListener('online',()=>{if(native&&backupInfo().auto)Native.backupAuto()});
initializeUpdate();render();lockApp();syncHealth();openHealthTarget();


